```java
package com.example.orders;

import java.util.Map;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication
public class OrderApplication {
    public static void main(String[] args) {
        SpringApplication.run(OrderApplication.class, args);
    }
}

@RestController
class StatusController {
    @GetMapping("/status")
    Map<String, String> status() {
        return Map.of("status", "ready");
    }
}
```

With the web starter on the classpath, Boot configures the Spring MVC infrastructure and an embedded servlet server. The application contributes the controller; Boot does not invent the endpoint or its business behaviour.

